#include "wsoundportal89.h"
static wsound89_i16 sat(wsound89_i32 v){if(v>32767)return 32767;if(v<-32768)return -32768;return(wsound89_i16)v;}
wsound89_result wsoundportal89_init(wsoundportal89_context*c,wsound89_i16*m,wsound89_u32 cap,wsound89_u32 delay){wsound89_u32 i;if(!c||!m||cap<2||delay>=cap)return WSOUND89_EINVAL;c->memory=m;c->capacity=cap;c->index=0;c->delay=delay;c->low=c->midlow=0;c->low_q15=26000;c->mid_q15=18000;c->high_q15=8000;c->opening_q15=20000;for(i=0;i<cap;i++)m[i]=0;return WSOUND89_OK;}
wsound89_result wsoundportal89_set_path(wsoundportal89_context*c,wsound89_u32 delay,wsound89_u16 l,wsound89_u16 m,wsound89_u16 h,wsound89_u16 o){if(!c||delay>=c->capacity)return WSOUND89_EINVAL;c->delay=delay;c->low_q15=l;c->mid_q15=m;c->high_q15=h;c->opening_q15=o;return WSOUND89_OK;}
wsound89_i16 wsoundportal89_process_sample(wsoundportal89_context*c,wsound89_i16 in){wsound89_u32 pos;wsound89_i32 d,lo,mi,hi,out;if(!c||!c->memory)return in;c->memory[c->index]=in;pos=(c->index+c->capacity-c->delay)%c->capacity;d=c->memory[pos];c->low+=(d-c->low)>>5;c->midlow+=(d-c->midlow)>>2;lo=c->low;mi=c->midlow-lo;hi=d-c->midlow;out=((lo*c->low_q15)+(mi*c->mid_q15)+(hi*c->high_q15))>>15;out=(out*c->opening_q15)>>15;c->index++;if(c->index>=c->capacity)c->index=0;return sat(out);}
